Simplicite.UI.BusinessObjects.DemoOrder=class extends Simplicite.UI.BusinessObject{onLoadForm(ctn,obj,params){super.onLoadForm(ctn,obj,params);const pup=$ui.getUIField(ctn,obj,'demoOrdPrdId.demoPrdUnitPrice').ui;const up=$ui.getUIField(ctn,obj,'demoOrdUnitPrice').ui;const q=$ui.getUIField(ctn,obj,'demoOrdQuantity').ui;const t=$ui.getUIField(ctn,obj,'demoOrdTotal').ui;const v=$ui.getUIField(ctn,obj,'demoOrdVAT').ui;const calcTotal=()=>{t?.val((q?.val()||0)*(up?.val()||0));v?.val((t?.val()||0)*($grant.sysparams?.DEMO_VAT||0)/100);};pup?.on('change',()=>{up?.val(pup?.val()||0);calcTotal();});q?.on('change',calcTotal);}};